/**
 * Phase 4b-2: the TypeScript port of tools/dental-synth/gen_dental_set.py, proven with no Python installed.
 *  1. Python-compatibility modules (src/synth/pyrandom.ts, pydecimal.ts, pycsv.ts) against Python 3.10's own outputs in
 *     test/golden/dental-port.golden.json (written by tools/dental-synth/compare_port.py --write-golden).
 *  2. Byte identity: three reference sets generated by the port have the SHA-256 of every CSV Python wrote, and truth.json
 *     equal as JSON (flags.out aside).
 *  3. L5 seed sweep: every scenario x seed (x leak seed) is generated in memory into a temp folder and scripts/reconcile-check.ts
 *     must reproduce its answer key (matches and diagnosed exceptions). Grid: env DENTAL_SWEEP_SEEDS (default "1-3") and
 *     DENTAL_SWEEP_LEAK_SEEDS (default "1"), each "a-b" or a comma list.
 */
import { test } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { spawnSync } from "node:child_process";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { PyRandom } from "../src/synth/pyrandom.ts";
import { Dec, decFromFloat, pyFloatStr, type Rounding } from "../src/synth/pydecimal.ts";
import { csvRow } from "../src/synth/pycsv.ts";
import { FLAG_SPEC, GenError, SCENARIOS, defaultFlags, generate, type DentalFlags } from "../src/synth/dental-gen.ts";

const G = JSON.parse(readFileSync(fileURLToPath(new URL("./golden/dental-port.golden.json", import.meta.url)), "utf8"));
const hexToF = (h: string) => new DataView(Uint8Array.from(h.match(/../g)!, (b) => parseInt(b, 16)).buffer).getFloat64(0);
const fHex = (x: number) => { const d = new DataView(new ArrayBuffer(8)); d.setFloat64(0, x); return Array.from(new Uint8Array(d.buffer), (b) => b.toString(16).padStart(2, "0")).join(""); };

function flagsFrom(argv: string[], out: string): DentalFlags {
  const over: Record<string, unknown> = {};
  for (let i = 0; i < argv.length; i += 2) {
    const k = argv[i].slice(2).replaceAll("-", "_") as keyof DentalFlags, kind = FLAG_SPEC[k].kind;
    over[k] = kind === "str" ? argv[i + 1] : Number(argv[i + 1]);
  }
  return defaultFlags(out, over as Partial<DentalFlags>);
}

test(`pyrandom matches Python ${G.python} random.Random (${G.rng.length} seeds incl. 0, negative, 2^32, 2^64+5, leak-stream seeds)`, () => {
  for (const [seed, seq] of G.rng) {
    const r = new PyRandom(BigInt(seed));
    for (const [op, ...v] of seq) {
      const want = v[v.length - 1];
      const got = op === "random" ? fHex(r.random()) : op === "randrange2" ? r.randrange(v[0], v[1]) : op === "randint" ? r.randint(v[0], v[1])
        : op === "choice" ? r.choice(Array.from({ length: v[0] }, (_, i) => i)) : op === "uniform" ? fHex(r.uniform(v[0], v[1]))
        : op === "choices" ? r.choices(Array.from({ length: 10 }, (_, i) => i), v[0])[0]
        : op === "shuffle" ? (() => { const x = Array.from({ length: v[0] }, (_, i) => i); r.shuffle(x); return x; })()
        : op === "randrange1" ? r.randrange(v[0]) : r.getrandbits(v[0]).toString();
      assert.deepEqual(got, want, `seed ${seed} ${op}`);
    }
  }
});

test(`pyFloatStr is Python's str(float) (${G.floats.length} floats: +-0, subnormal, max, the 1e16 and 1e-4 switches, random bit patterns)`, () => {
  for (const [h, s] of G.floats) assert.equal(pyFloatStr(hexToF(h)), s, h);
});

test(`Dec matches Python's decimal (${G.dec.length} operations: add, sub, mul, neg, quantize, div, format, cmp, int, Decimal(str(float)))`, () => {
  for (const [op, ...v] of G.dec) {
    if (op === "add") assert.equal(Dec.of(v[0]).add(Dec.of(v[1])).toString(), v[2], `${v[0]} + ${v[1]}`);
    else if (op === "sub") assert.equal(Dec.of(v[0]).sub(Dec.of(v[1])).toString(), v[2], `${v[0]} - ${v[1]}`);
    else if (op === "mul") assert.equal(Dec.of(v[0]).mul(Dec.of(v[1])).toString(), v[2], `${v[0]} * ${v[1]}`);
    else if (op === "neg") assert.equal(Dec.of(v[0]).neg().toString(), v[1], `-${v[0]}`);
    else if (op === "quantize") assert.equal(Dec.of(v[0]).quantize(v[1], v[2] as Rounding).toString(), v[3], `${v[0]} q ${v[1]} ${v[2]}`);
    else if (op === "format") assert.deepEqual([Dec.of(v[0]).format(2), Dec.of(v[0]).format(2, true)], [v[1], v[2]], `format ${v[0]}`);
    else if (op === "cmp") assert.deepEqual([Dec.of(v[0]).cmp(Dec.of(v[1])), Number(Dec.of(v[0]).toBigInt())], [v[2], v[3]], `cmp ${v[0]} ${v[1]}`);
    else if (op === "fromfloat") assert.equal(decFromFloat(hexToF(v[0])).quantize(-2, "ROUND_HALF_UP").toString(), v[1], v[0]);
    else if (op === "div") assert.equal(Dec.of(v[0]).div(Dec.of(v[1])).toString(), v[2], `${v[0]} / ${v[1]}`);
    else assert.fail(`unknown op ${op}`);
  }
});

test(`csvRow is Python's csv.writer (QUOTE_MINIMAL, CRLF; ${G.csv.length} rows with commas, quotes, CR, LF, empty and non-ASCII fields)`, () => {
  for (const [row, want] of G.csv) assert.equal(csvRow(row), want, JSON.stringify(row));
});

for (const ref of G.sets) {
  test(`byte identity with gen_dental_set.py: ${ref.flags.join(" ")}`, () => {
    const set = generate(flagsFrom(ref.flags, "unused"));
    const sha: Record<string, string> = {};
    for (const [rel, text] of set.files) if (!rel.endsWith(".json")) sha[rel] = createHash("sha256").update(text, "utf8").digest("hex");
    assert.deepEqual(sha, ref.sha256);
    const truth = JSON.parse(set.files.get("_answer-key/truth.json")!);
    delete truth.flags.out;
    assert.deepEqual(truth, ref.truth);
  });
}

test("refuses what the Python script refuses, with its message", () => {
  assert.throws(() => generate(defaultFlags("x", { patients: 5000 })), (e) => e instanceof GenError && e.message === "--patients max is 2208");
  assert.throws(() => generate(defaultFlags("x", { scenario: "neg-nope" })), GenError);
  assert.throws(() => generate(defaultFlags("x", { start: "2024-02-30" })), GenError);
});

const span = (s: string) => s.split(",").flatMap((p) => { const [a, b] = p.split("-").map(Number); return Array.from({ length: (b ?? a) - a + 1 }, (_, i) => a + i); });
const seeds = span(process.env.DENTAL_SWEEP_SEEDS ?? "1-3"), leakSeeds = span(process.env.DENTAL_SWEEP_LEAK_SEEDS ?? "1");
const script = fileURLToPath(new URL("../scripts/reconcile-check.ts", import.meta.url));
const tmpRoot = mkdtempSync(join(tmpdir(), "dental-sweep-"));
test.after(() => rmSync(tmpRoot, { recursive: true, force: true }));
for (const scenario of SCENARIOS) for (const seed of seeds) for (const ls of scenario === "pos" ? [1] : leakSeeds) {
  test(`L5 sweep ${scenario} seed ${seed} leak-seed ${ls}: reconcile-check reproduces the generated answer key`, (t) => {
    const out = join(tmpRoot, `${scenario}-s${seed}-l${ls}`);
    let set;
    try { set = generate(defaultFlags(out, { scenario, seed, leak_seed: ls })); }
    catch (e) { if (e instanceof GenError) { t.skip(`generator refused this seed (as Python would): ${e.message}`); return; } throw e; }
    for (const [rel, text] of set.files) { const p = join(out, rel); mkdirSync(dirname(p), { recursive: true }); writeFileSync(p, text, "utf8"); }
    const r = spawnSync(process.execPath, [script, "--folder", out, "--json"], { encoding: "utf8", timeout: 120000 });
    assert.equal(r.status, 0, `${r.stdout}${r.stderr}`);
    const s = JSON.parse(r.stdout);
    assert.deepEqual([s.missing, s.extra, s.missingExceptions, s.extraExceptions, s.failedChecks], [[], [], [], [], []]);
  });
}
